<template>
  <div class="mobile-page">
    <div class="mobile-header"><button class="back-button" @click="$router.back()">‹</button><b>青贮饲料管理</b><span></span></div>
    <div class="tabs"><button :class="{active: tab === 'plan'}" @click="tab='plan'">种植计划填报</button><button :class="{active: tab === 'storage'}" @click="tab='storage'">收储信息填报</button></div>
    <section v-if="tab === 'plan'" class="card"><div class="card-title">青贮种植计划</div><el-form label-position="top"><el-form-item label="种植品种"><el-select v-model="plan.crop" style="width:100%"><el-option label="青贮玉米" value="青贮玉米"/><el-option label="青贮高粱" value="青贮高粱"/><el-option label="苜蓿" value="苜蓿"/></el-select></el-form-item><el-form-item label="计划种植面积（亩）"><el-input-number v-model="plan.area" :min="0" style="width:100%"/></el-form-item><el-form-item label="对应地块"><el-checkbox-group v-model="plan.plotIds"><el-checkbox v-for="plot in plots" :key="plot.id" :label="plot.id">{{ plot.name }}（{{ plot.areaMu }}亩）</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="预计产量（吨）"><el-input-number v-model="plan.expectedYield" :min="0" style="width:100%"/></el-form-item></el-form><div class="actions"><el-button @click="savePlan">保存草稿</el-button><el-button type="primary" @click="submitPlan">提交种植计划</el-button></div></section>
    <section v-else class="card"><div class="card-title">青贮作物收储申报</div><el-form label-position="top"><el-form-item label="收储青贮饲料品种"><el-select v-model="storage.crop" style="width:100%"><el-option label="青贮玉米" value="青贮玉米"/><el-option label="青贮高粱" value="青贮高粱"/><el-option label="苜蓿" value="苜蓿"/></el-select></el-form-item><el-form-item label="收储价格（元/吨）"><el-input-number v-model="storage.price" :min="0" style="width:100%"/></el-form-item><el-form-item label="收储重量（吨）"><el-input-number v-model="storage.weight" :min="0" style="width:100%"/></el-form-item></el-form><div class="actions"><el-button type="primary" @click="submitStorage">提交收储信息</el-button></div></section>
    <section class="card"><div class="card-title">我的提交记录</div><div class="record"><span>种植计划</span><el-tag size="small" type="success">{{ planStatus }}</el-tag></div><div class="record"><span>收储申报</span><el-tag size="small" type="warning">{{ storageStatus }}</el-tag></div></section>
  </div>
</template>
<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { fetchSilPlots, submitDeclaration } from '@/api/sil'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const tab = ref('plan'); const plots = ref([]); const planStatus = ref('未提交'); const storageStatus = ref('未提交'); const plan = reactive({ crop: '青贮玉米', area: 0, plotIds: [], expectedYield: 0 }); const storage = reactive({ crop: '青贮玉米', price: 0, weight: 0 }); const savePlan = () => { localStorage.setItem('sil-mobile-plan-draft', JSON.stringify(plan)); ElMessage.success('种植计划草稿已保存') }; const submitPlan = async () => { if (!plan.area || !plan.expectedYield || !plan.plotIds.length) return ElMessage.warning('请填写面积、预计产量并选择对应地块'); const result = await submitDeclaration({ subjectId: userStore.role?.subjectId, crop: plan.crop, area: plan.area, expectedYield: plan.expectedYield, plotIds: plan.plotIds, year: 2026 }, userStore.role); if (!result.success) return ElMessage.error(result.message); planStatus.value = '已提交待审核'; ElMessage.success('青贮种植计划已提交') }; const submitStorage = async () => { if (!storage.price || !storage.weight) return ElMessage.warning('请填写收储价格和收储重量'); const result = await submitDeclaration({ subjectId: userStore.role?.subjectId, crop: storage.crop, price: storage.price, supplementArea: storage.weight, isSupplement: true, year: 2026 }, userStore.role); if (!result.success) return ElMessage.error(result.message); storageStatus.value = '已提交待审核'; ElMessage.success('青贮收储信息已提交') }; onMounted(async () => { plots.value = await fetchSilPlots(userStore.role, userStore.role?.subjectId); const draft = JSON.parse(localStorage.getItem('sil-mobile-plan-draft') || 'null'); if (draft) Object.assign(plan, draft) })
</script>
<style lang="scss" scoped>
.mobile-page{background:#f5f6f8;padding:0 12px 24px}.mobile-header{height:58px;display:grid;grid-template-columns:42px 1fr 42px;align-items:center;text-align:center;font-size:20px}.back-button{border:0;background:none;font-size:38px;text-align:left}.tabs{display:flex;background:#fff;border-radius:12px;padding:4px;margin-bottom:12px}.tabs button{flex:1;border:0;background:none;padding:10px;color:#667085}.tabs button.active{background:#eaf7ee;color:#21834d;border-radius:9px;font-weight:600}.card{background:#fff;border-radius:14px;padding:16px;margin-bottom:12px}.card-title{font-weight:700;color:#243b5a;margin-bottom:15px}.actions{display:flex;justify-content:flex-end;gap:8px}.record{display:flex;justify-content:space-between;border-top:1px solid #edf0f5;padding:12px 0}.mobile-page :deep(.el-form-item){margin-bottom:15px}.mobile-page :deep(.el-checkbox){display:block;margin:0 0 10px}
</style>